// Item catalogue: equipment (generated by tier), consumables, upgrade scrolls, and monster drops.
// Every equip has 7 upgrade slots. Drops roll a little stat variance; shop items don't.

export const EQUIP_SLOTS = ['weapon', 'hat', 'top', 'bottom', 'shoes', 'gloves', 'cape', 'earring'];
export const UPGRADE_SLOTS = 7;

export const ITEMS = {};

function add(def) {
  ITEMS[def.id] = def;
  return def;
}

// ---------- Weapons ----------
// Every weapon type (sword, axe, spear, wand, staff, bow, crossbow, dagger, claw; see
// core/formulas.js) comes in five progression tiers, `${type}_0` to `${type}_4`, and six endgame
// designs, `${type}_${theme}`. A weapon item is an equip with slot 'weapon', a `weaponType`, a
// `tier`, and for endgame ones a `theme`, which is also its `element`: the glow, footsteps, and
// hit impacts it brings.

export const ELEMENT_NAMES = {
  holy: 'Holy', cosmic: 'Cosmic', storm: 'Lightning', fire: 'Fire', water: 'Water',
  demonic: 'Demonic', bone: 'Necrotic', laser: 'Photon', chainsaw: 'Shred', cyber: 'Cyber',
};

// Per type: how hard it hits relative to a sword, magic attack for wands and staves, the main
// stat its wielders want, and its names (five tiers, then the endgame themes).
const WEAPON_LINES = {
  sword: { scale: 1.0, main: 'str', names: ['Wooden Sword', 'Iron Sword', 'Steel Longsword', 'Mithril Blade', 'Runeblade'], themes: { holy: "Seraph's Grace", demonic: 'Hellbringer', bone: 'Ossuary Edge', laser: 'Photon Saber', chainsaw: 'Ripper', cyber: 'Neon Katana' } },
  axe: { scale: 0.95, main: 'str', names: ['Stone Hatchet', 'Iron Axe', 'Steel Battleaxe', 'Mithril Cleaver', 'Runic Greataxe'], themes: { holy: 'Dawnbreaker', demonic: 'Abyssal Reaver', bone: 'Gravedigger', laser: 'Plasma Cleaver', chainsaw: 'Buzzkill', cyber: 'Glitch Axe' } },
  spear: { scale: 0.85, main: 'str', names: ['Bamboo Spear', 'Iron Spear', 'Steel Pike', 'Mithril Lance', 'Runic Glaive'], themes: { holy: "Archangel's Lance", demonic: 'Infernal Trident', bone: 'Spine Lance', laser: 'Ion Lance', chainsaw: 'Shredder Pike', cyber: 'Synapse Spear' } },
  wand: { scale: 0.5, matk: 0.9, main: 'int', names: ['Twig Wand', 'Iron Wand', 'Star Wand', 'Crescent Wand', 'Runic Wand'], themes: { holy: "Cherub's Kiss", demonic: 'Hexfang Wand', bone: 'Bonecaller', laser: 'Beam Wand', chainsaw: 'Buzz Wand', cyber: 'Holo Wand' } },
  staff: { scale: 0.55, matk: 1, main: 'int', names: ['Crooked Staff', 'Caged Staff', 'Moonlit Staff', 'Mithril Staff', 'Runic Staff'], themes: { holy: "Seraphim's Halo", demonic: 'Staff of the Pit', bone: 'Lich Scepter', laser: 'Photon Scepter', chainsaw: 'Sawblade Staff', cyber: 'Neuromancer Rod' } },
  bow: { scale: 0.8, main: 'dex', names: ['Shortbow', 'Iron Bow', 'Steel Recurve', 'Mithril Longbow', 'Runic Bow'], themes: { holy: 'Wings of Dawn', demonic: 'Hellstring', bone: 'Ribcage Bow', laser: 'Photon Bow', chainsaw: 'Sawtooth Bow', cyber: 'Neon Arc' } },
  crossbow: { scale: 0.78, main: 'dex', names: ['Wooden Crossbow', 'Iron Crossbow', 'Steel Arbalest', 'Mithril Crossbow', 'Runic Arbalest'], themes: { holy: 'Judgment', demonic: 'Doombolt', bone: 'Marrow Repeater', laser: 'Railgun', chainsaw: 'Sawlauncher', cyber: 'Cyber Repeater' } },
  dagger: { scale: 0.98, main: 'luk', names: ['Wooden Knife', 'Iron Dagger', 'Steel Dirk', 'Mithril Stiletto', 'Runic Kris'], themes: { holy: "Angel's Feather", demonic: 'Hellfang', bone: 'Bone Shiv', laser: 'Photon Knife', chainsaw: 'Revblade', cyber: 'Glitchblade' } },
  claw: { scale: 0.75, main: 'luk', names: ['Leather Claw', 'Iron Claw', 'Steel Talons', 'Mithril Talons', 'Runic Talons'], themes: { holy: 'Seraph Talons', demonic: 'Demon Grip', bone: 'Grave Hand', laser: 'Photon Claws', chainsaw: 'Shred Claws', cyber: 'Neon Talons' } },
};

const TIER_LEVELS = [0, 10, 20, 30, 40];
const TIER_WATK = [14, 26, 40, 56, 70];
const TIER_MATK = [10, 20, 34, 50, 66];
const TIER_COLORS = ['#e9c48f', '#c7ced9', '#e6edf7', '#bfe6ff', '#7ffcff'];
const ENDGAME_WATK = 92;
const ENDGAME_MATK = 96;

// What each endgame theme adds on top of the weapon's attack. `main` is the type's main stat.
const THEME_BONUS = {
  holy: (main) => ({ [main]: 8, hp: 200, mdef: 25 }),
  demonic: (main) => ({ [main]: 14, watkPct: 0.08 }),
  bone: (main) => ({ [main]: 10, hp: 150, eva: 12 }),
  laser: (main) => ({ [main]: 12, acc: 25 }),
  chainsaw: (main) => ({ [main]: 6, watkPct: 0.14 }),
  cyber: (main) => ({ [main]: 10, speed: 8, eva: 10, jump: 4 }),
};
const THEME_COLORS = { holy: '#ffe36b', demonic: '#ff3b2b', bone: '#6bff9a', chainsaw: '#ffb03b', cyber: '#3bf0ff' };
const LASER_COLORS = { sword: '#4fd8ff', axe: '#ff4f6b', spear: '#7dff6b', wand: '#ff6bf0', staff: '#b48cff', bow: '#5ff3ff', crossbow: '#ffcf4f', dagger: '#ff4f6b', claw: '#7dff6b' };

export const ENDGAME_THEMES = ['holy', 'demonic', 'bone', 'laser', 'chainsaw', 'cyber'];

for (const [type, line] of Object.entries(WEAPON_LINES)) {
  line.names.forEach((name, t) => {
    const stats = { watk: Math.round(TIER_WATK[t] * line.scale) };
    if (line.matk) stats.matk = Math.round(TIER_MATK[t] * line.matk);
    add({
      id: `${type}_${t}`, name, type: 'equip', slot: 'weapon', weaponType: type, tier: t, element: null,
      reqLevel: TIER_LEVELS[t], family: null, stats, price: Math.round(100 + 160 * t * t + 400 * t), color: TIER_COLORS[t],
    });
  });
  for (const theme of ENDGAME_THEMES) {
    const { watkPct = 0, ...bonus } = THEME_BONUS[theme](line.main);
    const stats = { watk: Math.round(ENDGAME_WATK * line.scale * (1 + watkPct)), ...bonus };
    if (line.matk) stats.matk = Math.round(ENDGAME_MATK * line.matk * (1 + watkPct));
    add({
      // The holy staff keeps the id it first shipped with, so saved ones carry over.
      id: type === 'staff' && theme === 'holy' ? 'seraphim_staff' : `${type}_${theme}`,
      name: line.themes[theme], type: 'equip', slot: 'weapon', weaponType: type, tier: 5, theme, element: theme,
      reqLevel: 50, family: null, endgame: true, stats, price: 250000,
      color: theme === 'laser' ? LASER_COLORS[type] : THEME_COLORS[theme],
    });
  }
}

export const WEAPON_IDS = Object.values(ITEMS).filter((d) => d.slot === 'weapon').map((d) => d.id);

// ---------- Armor ----------

const ARMOR_TIERS = [
  { level: 0, prefix: 'Cotton', color: '#ffc2d6' },
  { level: 10, prefix: 'Linen', color: '#a8dcff' },
  { level: 20, prefix: 'Leather', color: '#ffb38a' },
  { level: 30, prefix: 'Silver', color: '#c9d6ff' },
  { level: 40, prefix: 'Starlit', color: '#ffe98a' },
  { level: 50, prefix: 'Celestial', color: '#d2b8ff' },
];

// Each tier has its own name and look (`design`), so upgrades show on the character.
const ARMOR_KINDS = {
  hat: { labels: ['Beanie', 'Sun Hat', 'Cap', 'Helm', 'Witch Hat', 'Circlet'], designs: ['beanie', 'sunhat', 'cap', 'helmet', 'witch', 'circlet'], def: (t) => 3 + t * 6, extra: (t) => ({ hp: t * 10 }) },
  top: { labels: ['Tee', 'Striped Shirt', 'Vest', 'Breastplate', 'Star Robe', 'Celestial Robe'], designs: ['tee', 'stripes', 'vest', 'plate', 'starrobe', 'celestial'], def: (t) => 5 + t * 8, extra: () => ({}) },
  bottom: { labels: ['Shorts', 'Trousers', 'Chaps', 'Greaves', 'Star Skirt', 'Celestial Skirt'], designs: ['shorts', 'pants', 'leather', 'greaves', 'starskirt', 'celestialskirt'], def: (t) => 3 + t * 6, extra: () => ({}) },
  shoes: { labels: ['Sneakers', 'Boots', 'Riding Boots', 'Sabatons', 'Star Boots', 'Wing Boots'], designs: ['sneakers', 'boots', 'leatherboots', 'sabatons', 'starboots', 'wingboots'], def: (t) => 2 + t * 3, extra: (t) => ({ speed: t >= 2 ? 2 + t : 0 }) },
  gloves: { labels: ['Mittens', 'Gloves', 'Cuffed Gloves', 'Gauntlets', 'Star Gloves', 'Celestial Gauntlets'], designs: ['mitten', 'mitten', 'cuffed', 'gauntlet', 'cuffed', 'gauntlet'], def: (t) => 2 + t * 3, extra: (t) => ({ watk: t >= 2 ? t - 1 : 0, acc: 1 + t }) },
  cape: { labels: ['Scarf Cape', 'Cloak', 'Traveler Cloak', 'Royal Mantle', 'Star Cape', 'Celestial Mantle'], designs: ['short', 'long', 'long', 'royal', 'starcape', 'royal'], def: (t) => 2 + t * 4, extra: (t) => ({ mdef: 2 + t * 4, eva: t }) },
  earring: { labels: ['Studs', 'Studs', 'Drops', 'Drops', 'Star Drops', 'Star Drops'], designs: ['stud', 'stud', 'drop', 'drop', 'star', 'star'], def: () => 0, extra: (t) => ({ matk: 1 + t * 2, mp: 10 + t * 15 }) },
};

for (const [slot, kind] of Object.entries(ARMOR_KINDS)) {
  ARMOR_TIERS.forEach((tier, t) => {
    const stats = { wdef: kind.def(t), ...kind.extra(t) };
    for (const k of Object.keys(stats)) if (!stats[k]) delete stats[k];
    add({
      id: `${slot}_${t}`,
      name: `${tier.prefix} ${kind.labels[t]}`,
      type: 'equip',
      slot,
      design: kind.designs[t],
      tier: t,
      reqLevel: tier.level,
      family: null,
      stats,
      price: Math.round(60 + 90 * t * t + 250 * t),
      color: tier.color,
    });
  });
}

// ---------- Unique gear ----------
// One-of-a-kind outfits. Stats match the armor tier for their level, a little better.

const tierAt = (tiers, level) => tiers.reduce((best, t, i) => (t.level <= level ? i : best), 0);

const UNIQUE_ARMOR = [
  { id: 'hoodie', name: 'Comfy Hoodie', slot: 'top', design: 'hoodie', level: 5, color: '#c9b8ff', bonus: { eva: 2 } },
  { id: 'kitty_ears', name: 'Kitty Ears', slot: 'hat', design: 'kitty', level: 8, color: '#ffb3d1', bonus: { luk: 2, eva: 2 } },
  { id: 'sailor_top', name: 'Sailor Blouse', slot: 'top', design: 'sailor', level: 12, color: '#6f9cff', bonus: { dex: 2 } },
  { id: 'bunny_hood', name: 'Bunny Hood', slot: 'hat', design: 'bunny', level: 15, color: '#ffffff', bonus: { hp: 40, jump: 4 } },
  { id: 'fairy_wings', name: 'Fairy Wings', slot: 'cape', design: 'fairy', level: 15, color: '#c9f2ff', bonus: { speed: 4, mp: 30 } },
  { id: 'kimono', name: 'Blossom Kimono', slot: 'top', design: 'kimono', level: 18, color: '#ffb3d9', bonus: { int: 2, mdef: 10 } },
  { id: 'flower_crown', name: 'Flower Crown', slot: 'hat', design: 'flowers', level: 20, color: '#ff9ec0', bonus: { matk: 4, mp: 40 } },
  { id: 'star_beret', name: 'Star Beret', slot: 'hat', design: 'beret', level: 30, color: '#8fa8ff', bonus: { dex: 3, luk: 3 } },
  { id: 'angel_wings', name: 'Angel Wings', slot: 'cape', design: 'angel', level: 35, color: '#ffffff', bonus: { speed: 6, mdef: 20, hp: 80 } },
  { id: 'star_cape', name: 'Galaxy Cape', slot: 'cape', design: 'starcape', level: 40, color: '#5d6fd6', bonus: { str: 3, dex: 3, int: 3, luk: 3 } },
  { id: 'crystal_crown', name: 'Crystal Crown', slot: 'hat', design: 'crown', level: 45, color: '#8fe3ff', bonus: { hp: 120, mp: 120, matk: 6 } },
  // Everyday clothing.
  { id: 'denim_jacket', name: 'Denim Jacket', slot: 'top', design: 'jacket', level: 6, color: '#7f9fd8', bonus: { dex: 1 } },
  { id: 'cozy_sweater', name: 'Cozy Sweater', slot: 'top', design: 'sweater', level: 6, color: '#ffcf9e', bonus: { hp: 20 } },
  { id: 'overalls', name: 'Comfy Overalls', slot: 'top', design: 'overalls', level: 7, color: '#8fb4ff', bonus: { str: 1, hp: 15 } },
  { id: 'sundress', name: 'Sundress', slot: 'top', design: 'dress', level: 9, color: '#ffe36b', bonus: { luk: 2 } },
  { id: 'school_blazer', name: 'School Blazer', slot: 'top', design: 'blazer', level: 10, color: '#4f5d9a', bonus: { int: 2 } },
  { id: 'puffer_jacket', name: 'Puffer Jacket', slot: 'top', design: 'puffer', level: 12, color: '#ff9b7a', bonus: { hp: 40, mdef: 6 } },
  { id: 'maid_dress', name: 'Maid Dress', slot: 'top', design: 'maid', level: 14, color: '#3b3650', bonus: { dex: 2, luk: 2 } },
  { id: 'pleated_skirt', name: 'Pleated Skirt', slot: 'bottom', design: 'skirt', level: 6, color: '#ff9ec0', bonus: { speed: 2 } },
  { id: 'blue_jeans', name: 'Blue Jeans', slot: 'bottom', design: 'jeans', level: 6, color: '#6f8fcf', bonus: { hp: 15 } },
  { id: 'cargo_pants', name: 'Cargo Pants', slot: 'bottom', design: 'cargo', level: 10, color: '#9aa07a', bonus: { str: 1, dex: 1 } },
  { id: 'long_skirt', name: 'Long Skirt', slot: 'bottom', design: 'longskirt', level: 12, color: '#b9a7ff', bonus: { mp: 30, mdef: 6 } },
];

for (const u of UNIQUE_ARMOR) {
  const kind = ARMOR_KINDS[u.slot];
  const t = tierAt(ARMOR_TIERS, u.level);
  const stats = { wdef: Math.round(kind.def(t) * 1.1) + 1, ...kind.extra(t) };
  for (const [k, v] of Object.entries(u.bonus)) stats[k] = (stats[k] ?? 0) + v;
  for (const k of Object.keys(stats)) if (!stats[k]) delete stats[k];
  add({
    id: u.id, name: u.name, type: 'equip', slot: u.slot, design: u.design, unique: true,
    tier: t, reqLevel: u.level, family: null, stats, price: Math.round(300 + 140 * t * t + 400 * t), color: u.color,
  });
}

export const UNIQUE_IDS = UNIQUE_ARMOR.map((u) => u.id);

